/**
 * localdoc.org — DocxBuilder (In-Memory OpenXML .docx Generator)
 * Builds genuine Microsoft Word (.docx) OpenXML archives with rich formatting in pure client-side JavaScript.
 */
class DocxBuilder {
  static escapeXml(str) {
    if (!str && str !== 0) return '';
    return String(str)
      .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '') // remove invalid XML control chars
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  static createRunXml(run) {
    if (!run) return '';
    if (run.isTab) {
      return '<w:r><w:tab/></w:r>';
    }

    const text = this.escapeXml(run.text || '');
    if (!text && !run.isTab) return '';

    let rPr = '<w:rPr>';
    const font = this.escapeXml(run.fontFamily || 'Calibri');
    rPr += `<w:rFonts w:ascii="${font}" w:hAnsi="${font}" w:cs="${font}"/>`;

    if (run.bold) {
      rPr += '<w:b/><w:bCs/>';
    }
    if (run.italic) {
      rPr += '<w:i/><w:iCs/>';
    }
    if (run.underline) {
      rPr += '<w:u w:val="single"/>';
    }
    if (run.fontSize) {
      const halfPoints = Math.round(run.fontSize);
      rPr += `<w:sz w:val="${halfPoints}"/><w:szCs w:val="${halfPoints}"/>`;
    }
    if (run.color) {
      const hex = String(run.color).replace('#', '');
      rPr += `<w:color w:val="${hex}"/>`;
    }
    rPr += '</w:rPr>';

    return `<w:r>${rPr}<w:t xml:space="preserve">${text}</w:t></w:r>`;
  }

  static createParagraphXml(p) {
    if (!p) return '<w:p/>';

    // If it's a simple string, wrap in default paragraph
    if (typeof p === 'string') {
      const clean = this.escapeXml(p);
      return `<w:p><w:pPr><w:spacing w:before="60" w:after="60" w:line="240" w:lineRule="auto"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Calibri"/><w:sz w:val="22"/></w:rPr><w:t xml:space="preserve">${clean}</w:t></w:r></w:p>`;
    }

    // Handle divider rule
    if (p.type === 'divider') {
      return `<w:p><w:pPr><w:pBdr><w:bottom w:val="single" w:sz="8" w:space="1" w:color="CBD5E1"/></w:pBdr><w:spacing w:before="120" w:after="120"/></w:pPr></w:p>`;
    }

    // Handle Table
    if (p.type === 'table' && Array.isArray(p.rows)) {
      return this.createTableXml(p);
    }

    // Build paragraph properties <w:pPr>
    let pPr = '<w:pPr>';
    
    // Alignment
    if (p.align && ['center', 'right', 'both', 'left'].includes(p.align)) {
      pPr += `<w:jc w:val="${p.align}"/>`;
    }

    // Spacing
    const before = p.spacingBefore !== undefined ? p.spacingBefore : (p.type === 'heading' ? 200 : (p.isBullet ? 40 : 60));
    const after = p.spacingAfter !== undefined ? p.spacingAfter : (p.type === 'heading' ? 80 : (p.isBullet ? 40 : 60));
    pPr += `<w:spacing w:before="${before}" w:after="${after}" w:line="240" w:lineRule="auto"/>`;

    // Bottom border (for Section Headings e.g. "EXPERIENCE", "EDUCATION")
    if (p.hasBottomBorder || (p.type === 'heading' && p.headingLevel <= 2)) {
      const bColor = p.borderColor || '94A3B8';
      pPr += `<w:pBdr><w:bottom w:val="single" w:sz="8" w:space="3" w:color="${bColor}"/></w:pBdr>`;
    }

    // Bullet indentation
    if (p.isBullet || p.type === 'bullet') {
      pPr += '<w:ind w:left="540" w:hanging="280"/>';
    }

    // Right-aligned Tab stop (e.g. Job Title on left, Dates on right)
    if (p.hasRightTab) {
      const tabPos = p.tabPos || 9072; // default right margin for A4 with 1 inch margin
      pPr += `<w:tabs><w:tab w:val="right" w:pos="${tabPos}"/></w:tabs>`;
    }

    pPr += '</w:pPr>';

    // Build runs
    let runsXml = '';
    
    // If bullet symbol is needed
    if ((p.isBullet || p.type === 'bullet') && !p.hasCustomBulletPrefix) {
      const bulletSymbol = p.bulletChar || '•';
      runsXml += `<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:b/><w:sz w:val="22"/><w:color w:val="334155"/></w:rPr><w:t xml:space="preserve">${this.escapeXml(bulletSymbol)} </w:t></w:r>`;
    }

    if (Array.isArray(p.runs)) {
      runsXml += p.runs.map(r => this.createRunXml(r)).join('');
    } else if (p.text) {
      runsXml += this.createRunXml({
        text: p.text,
        bold: p.bold || p.type === 'heading',
        italic: p.italic,
        underline: p.underline,
        fontSize: p.fontSize || (p.type === 'heading' ? (p.headingLevel === 1 ? 32 : 26) : 22),
        color: p.color || (p.type === 'heading' ? '0F172A' : '1E293B')
      });
    }

    return `<w:p>${pPr}${runsXml}</w:p>`;
  }

  static createTableXml(tableObj) {
    const rows = tableObj.rows || [];
    let trsXml = '';

    rows.forEach((row, rowIdx) => {
      let tcsXml = '';
      const cells = Array.isArray(row) ? row : (row.cells || []);
      
      cells.forEach(cell => {
        const text = typeof cell === 'string' ? cell : (cell.text || '');
        const isHeader = rowIdx === 0 || (cell && cell.isHeader);
        const bold = cell && cell.bold !== undefined ? cell.bold : isHeader;
        const width = (cell && cell.width) ? cell.width : Math.floor(9000 / Math.max(1, cells.length));
        const bgColor = isHeader ? '<w:shd w:val="clear" w:color="auto" w:fill="F1F5F9"/>' : '';

        tcsXml += `
          <w:tc>
            <w:tcPr>
              <w:tcW w:w="${width}" w:type="dxa"/>
              ${bgColor}
              <w:tcMar>
                <w:top w:w="120" w:type="dxa"/>
                <w:left w:w="140" w:type="dxa"/>
                <w:bottom w:w="120" w:type="dxa"/>
                <w:right w:w="140" w:type="dxa"/>
              </w:tcMar>
            </w:tcPr>
            <w:p>
              <w:pPr><w:spacing w:before="20" w:after="20"/></w:pPr>
              <w:r>
                <w:rPr>
                  <w:rFonts w:ascii="Calibri" w:hAnsi="Calibri"/>
                  ${bold ? '<w:b/><w:bCs/>' : ''}
                  <w:sz w:val="${isHeader ? '22' : '20'}"/>
                  <w:color w:val="${isHeader ? '0F172A' : '334155'}"/>
                </w:rPr>
                <w:t xml:space="preserve">${this.escapeXml(text)}</w:t>
              </w:r>
            </w:p>
          </w:tc>`;
      });

      trsXml += `<w:tr><w:trPr><w:cantSplit/></w:trPr>${tcsXml}</w:tr>`;
    });

    return `
      <w:tbl>
        <w:tblPr>
          <w:tblW w:w="9000" w:type="dxa"/>
          <w:tblBorders>
            <w:top w:val="single" w:sz="6" w:space="0" w:color="CBD5E1"/>
            <w:left w:val="single" w:sz="6" w:space="0" w:color="CBD5E1"/>
            <w:bottom w:val="single" w:sz="6" w:space="0" w:color="CBD5E1"/>
            <w:right w:val="single" w:sz="6" w:space="0" w:color="CBD5E1"/>
            <w:insideH w:val="single" w:sz="4" w:space="0" w:color="E2E8F0"/>
            <w:insideV w:val="single" w:sz="4" w:space="0" w:color="E2E8F0"/>
          </w:tblBorders>
          <w:tblCellMar>
            <w:top w:w="100" w:type="dxa"/>
            <w:left w:w="120" w:type="dxa"/>
            <w:bottom w:w="100" w:type="dxa"/>
            <w:right w:w="120" w:type="dxa"/>
          </w:tblCellMar>
        </w:tblPr>
        ${trsXml}
      </w:tbl>`;
  }

  static createDocxFromContent(paragraphs) {
    if (!Array.isArray(paragraphs)) {
      paragraphs = [paragraphs];
    }

    const pXml = paragraphs.map(p => this.createParagraphXml(p)).join('\n');

    const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
            xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"
            xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math"
            xmlns:v="urn:schemas-microsoft-com:vml"
            xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"
            xmlns:w10="urn:schemas-microsoft-com:office:word"
            xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"
            xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">
  <w:body>
    ${pXml}
    <w:sectPr>
      <w:pgSz w:w="11906" w:h="16838"/>
      <w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720" w:gutter="0"/>
      <w:cols w:space="720"/>
      <w:docGrid w:linePitch="360"/>
    </w:sectPr>
  </w:body>
</w:document>`;

    const contentTypesXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
  <Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>
</Types>`;

    const relsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>`;

    const stylesXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:docDefaults>
    <w:rPrDefault>
      <w:rPr>
        <w:rFonts w:ascii="Calibri" w:eastAsia="Calibri" w:hAnsi="Calibri" w:cs="Calibri"/>
        <w:sz w:val="22"/>
        <w:szCs w:val="22"/>
        <w:lang w:val="en-US" w:eastAsia="en-US" w:bidi="ar-SA"/>
      </w:rPr>
    </w:rPrDefault>
    <w:pPrDefault>
      <w:pPr>
        <w:spacing w:after="120" w:line="240" w:lineRule="auto"/>
      </w:pPr>
    </w:pPrDefault>
  </w:docDefaults>
  <w:style w:type="paragraph" w:default="1" w:styleId="Normal">
    <w:name w:val="Normal"/>
    <w:qFormat/>
  </w:style>
</w:styles>`;

    const zip = new MiniZip();
    zip.addFile("[Content_Types].xml", contentTypesXml);
    zip.addFile("_rels/.rels", relsXml);
    zip.addFile("word/document.xml", documentXml);
    zip.addFile("word/styles.xml", stylesXml);
    return zip.generateBlob("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
  }
}

class MiniZip {
  constructor() {
    this.files = [];
  }

  addFile(name, content) {
    const encoder = new TextEncoder();
    const data = typeof content === 'string' ? encoder.encode(content) : new Uint8Array(content);
    this.files.push({ name, data });
  }

  generateBlob(mimeType = "application/zip") {
    const parts = [];
    const cdEntries = [];
    let offset = 0;

    for (const file of this.files) {
      const nameBytes = new TextEncoder().encode(file.name);
      const dataBytes = file.data;
      const crc = this.crc32(dataBytes);
      const size = dataBytes.length;

      // Local file header (30 bytes + name)
      const localHeader = new Uint8Array(30 + nameBytes.length);
      const v = new DataView(localHeader.buffer);
      v.setUint32(0, 0x04034b50, true);
      v.setUint16(4, 20, true);
      v.setUint16(6, 0, true);
      v.setUint16(8, 0, true);
      v.setUint16(10, 0, true);
      v.setUint16(12, 0, true);
      v.setUint32(14, crc, true);
      v.setUint32(18, size, true);
      v.setUint32(22, size, true);
      v.setUint16(26, nameBytes.length, true);
      v.setUint16(28, 0, true);
      localHeader.set(nameBytes, 30);

      parts.push(localHeader);
      parts.push(dataBytes);

      // Central directory header (46 bytes + name)
      const cdHeader = new Uint8Array(46 + nameBytes.length);
      const cdv = new DataView(cdHeader.buffer);
      cdv.setUint32(0, 0x02014b50, true);
      cdv.setUint16(4, 20, true);
      cdv.setUint16(6, 20, true);
      cdv.setUint16(8, 0, true);
      cdv.setUint16(10, 0, true);
      cdv.setUint16(12, 0, true);
      cdv.setUint16(14, 0, true);
      cdv.setUint32(16, crc, true);
      cdv.setUint32(20, size, true);
      cdv.setUint32(24, size, true);
      cdv.setUint16(28, nameBytes.length, true);
      cdv.setUint16(30, 0, true);
      cdv.setUint16(32, 0, true);
      cdv.setUint16(34, 0, true);
      cdv.setUint16(36, 0, true);
      cdv.setUint32(38, 0, true);
      cdv.setUint32(42, offset, true);
      cdHeader.set(nameBytes, 46);

      cdEntries.push(cdHeader);
      offset += localHeader.length + dataBytes.length;
    }

    const cdOffset = offset;
    let cdSize = 0;
    for (const cd of cdEntries) {
      parts.push(cd);
      cdSize += cd.length;
    }

    const eocd = new Uint8Array(22);
    const eocdv = new DataView(eocd.buffer);
    eocdv.setUint32(0, 0x06054b50, true);
    eocdv.setUint16(4, 0, true);
    eocdv.setUint16(6, 0, true);
    eocdv.setUint16(8, this.files.length, true);
    eocdv.setUint16(10, this.files.length, true);
    eocdv.setUint32(12, cdSize, true);
    eocdv.setUint32(16, cdOffset, true);
    eocdv.setUint16(20, 0, true);

    parts.push(eocd);
    return new Blob(parts, { type: mimeType });
  }

  crc32(bytes) {
    let crc = -1;
    for (let i = 0; i < bytes.length; i++) {
      crc = (crc >>> 8) ^ MiniZip.CRC_TABLE[(crc ^ bytes[i]) & 0xff];
    }
    return (crc ^ (-1)) >>> 0;
  }
}

MiniZip.CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    }
    table[i] = c >>> 0;
  }
  return table;
})();

if (typeof window !== 'undefined') {
  window.DocxBuilder = DocxBuilder;
  window.MiniZip = MiniZip;
}
